async function classifyType(env, userText) {
  try {
    const anchors = ANCHOR_VECTORS;

    // 超过50字符只取前50个喂给AI做分类，节省neurons（不影响存到数据库/展示的原始文本）
    const textForEmbedding = userText.length > 50 ? userText.slice(0, 50) : userText;

    const userResult = await env.AI.run(EMBED_MODEL, { text: [textForEmbedding] });

    const userVector = userResult?.data?.[0];
    if (!userVector) return null;

     // 粗略估算本次消耗的 neurons（非精确计费值，仅供参考）
    const estimatedTokens = Math.ceil(textForEmbedding.length / 4);
    const estimatedNeurons = (estimatedTokens * 6058) / 1_000_000;
    console.log(
      "[classifyType] 输入长度:", textForEmbedding.length,
      "预估tokens:", estimatedTokens,
      "预估neurons:", estimatedNeurons.toFixed(4)
    );

    let bestType = null;
    let bestScore = -Infinity;

    for (const type of TYPE_WHITELIST) {
      const anchorVector = anchors[type];
      if (!anchorVector) continue;
      const score = cosineSimilarity(userVector, anchorVector);
      if (score > bestScore) {
        bestScore = score;
        bestType = type;
      }
    }

     console.log("[classifyType]", userText, "→ type:", bestType, "score:", bestScore);

    if (bestType && bestScore >= SIMILARITY_THRESHOLD) {
      return bestType;
    }
    return null;
  } catch (err) {
    console.error("[classifyType] embedding 分类失败:", err.message);
    return null;
  }
}

export async function onRequestPost(context) {
  const { env, request } = context;

  let lang, userText;
  try {
    const body = await request.json();
    lang = body?.lang;
    userText = body?.text ?? "";
  } catch {
    // 没有 body 或不是合法 JSON，走默认语言，且不做分类
  }

  const table = TABLE_MAP[lang] ?? DEFAULT_TABLE;

  // 用 embedding 判断语意类型，失败则 type 为 null（后面走不限定 type 的随机逻辑）
  const type = userText ? await classifyType(env, userText) : null;

  let result = null;

  if (type) {
    result = await env.DB.prepare(
      `SELECT text FROM ${table} WHERE type = ? ORDER BY RANDOM() LIMIT 1`
    )
      .bind(type)
      .first();
  }

  // 该语言表里没有这个 type 的数据（或没识别出 type），退化成不限定 type 的随机一条
  if (!result) {
    result = await env.DB.prepare(
      `SELECT text FROM ${table} ORDER BY RANDOM() LIMIT 1`
    ).first();
  }

  // 该语言表本身还没建/是空的，兜底回退到默认的 en 表
  if (!result && table !== DEFAULT_TABLE) {
    if (type) {
      result = await env.DB.prepare(
        `SELECT text FROM ${DEFAULT_TABLE} WHERE type = ? ORDER BY RANDOM() LIMIT 1`
      )
        .bind(type)
        .first();
    }
    if (!result) {
      result = await env.DB.prepare(
        `SELECT text FROM ${DEFAULT_TABLE} ORDER BY RANDOM() LIMIT 1`
      ).first();
    }
  }

  if (!result) {
    return new Response(JSON.stringify({ text: "数据库是空的,先去插几条数据吧。" }), {
      headers: { "Content-Type": "application/json" },
    });
  }

  return new Response(JSON.stringify({ text: result.text }), {
    headers: { "Content-Type": "application/json" },
  });
}
